//!Seasonal graphics use the actual CP pool and the existing late-FX allocator.
use super::{Game,Value};
use crate::original_display::{self as display,seasonal::{self,Cp}};
use crate::original_path_contact::game::Boundary;
#[derive(Clone)]pub(super) struct CpPool{records:[Cp;64],bindings:[Option<usize>;64]}
impl CpPool{
 pub(super) fn import(v:&Value)->Option<Self>{let rows=v["nativeAi"]["sectorRecords"].as_array().filter(|r|r.len()==64)?;let mut records=[Cp::default();64];let mut bindings=[None;64];for(slot,r)in rows.iter().enumerate(){let a=r["rect"].as_array().filter(|a|a.len()==4)?;for i in 0..4{records[slot].rect[i]=i16::try_from(a[i].as_i64()?).ok()?;}records[slot].owner=u8::try_from(r["owner"].as_u64()?).ok()?;bindings[slot]=v["sectors"].as_array().and_then(|s|s.iter().find(|s|s["nativeSlot"].as_u64()==Some(slot as u64))).and_then(|s|s["id"].as_u64()).map(|n|n as usize);}Some(Self{records,bindings})}
}
#[cfg(test)]mod tests{
 use super::*;use super::super::{effects,tests::field};use crate::{json,original_combat::OriginalRng};
 fn pool(owner:u8)->CpPool{let mut records=[Cp{rect:[-1,0,0,0],owner:0};64];records[63]=Cp{rect:[0,0,127,127],owner};CpPool{records,bindings:[None;64]}}
 fn game(owner:u8)->Game{let mut g=field();g.import_native_world(&Value::Null);g.native_world.as_mut().unwrap().seasonal_cps=Some(pool(owner));g.native_seasonal_mode=1;g}
 #[test]fn callback_keeps_three_pictures_and_snapshots_do_not_requery_cp_or_advance_the_clock(){let mut g=game(0);let mut object=g.make_object(1,[500,600],1).unwrap();object.sprite=5960;object.record.flags13=112;object.animation18=2;object.sprite_offset21=-1;g.native_world.as_mut().unwrap().objects[0]=Some(object);g.native_frame16=15;let before=g.original_rng.words;let crt=g.native_cosmetic_rng;g.update_native_world_objects();let rows=g.native_display.objects.clone().unwrap();assert_eq!(rows.len(),3);assert_eq!((rows[0].0.sprite,rows[1].0.sprite,rows[2].0.sprite),(5961,292,294));assert_eq!(rows[0].0.palette,255);assert_eq!(rows[1].0.palette,0);assert!(rows[2].1["nativeLiteralPalette"]==true);let a=g.native_display_queue();g.native_world.as_mut().unwrap().seasonal_cps.as_mut().unwrap().records[63].owner=1;g.native_frame16=0;assert_eq!(g.native_display_queue(),a);assert_eq!(g.original_rng.words,before);assert_eq!(g.native_cosmetic_rng,crt);g.update_native_world_objects();assert_eq!(g.native_display.objects.as_ref().unwrap()[1].0.palette,1);assert_eq!(g.native_display.objects.as_ref().unwrap()[2].0.sprite,293);}
 #[test]fn actual_cp_binding_preserves_raw_neutral_aliases_until_a_real_capture(){let mut g=game(20);let cp=g.native_world.as_mut().unwrap().seasonal_cps.as_mut().unwrap();cp.bindings[63]=Some(0);g.sectors[0].owner=-1;assert_eq!(g.native_seasonal_owner([500,600]),Ok(20));g.sectors[0].owner=1;assert_eq!(g.native_seasonal_owner([500,600]),Ok(1));g.native_world.as_mut().unwrap().seasonal_cps.as_mut().unwrap().records[1].rect=[1001,0,1002,1];assert_eq!(g.native_seasonal_owner([500,600]),Err(Boundary::SeasonalCpOutsideMode));g.native_world.as_mut().unwrap().seasonal_cps=None;assert_eq!(g.native_seasonal_owner([500,600]),Err(Boundary::SeasonalCpPool));}
 #[test]fn eight_emissions_force_the_source_gate_and_retain_tint_only_on_their_actual_slots(){for mp in[false,true]{for cap in[0,1,7,8,500]{for owner in[0,1,2,3,4,15,20,255]{let mut g=game(owner);g.multiplayer=mp;g.original_rng.multiplayer=mp;g.native_world.as_mut().unwrap().effects=vec![None;cap];g.native_world.as_mut().unwrap().effect_suppression=1;let mut rng=g.original_rng.clone();for _ in 0..cap.min(8)*5{rng.next_u32();}assert_eq!(g.emit_native_seasonal_particles([500,608]),Ok(cap.min(8)));let s=g.native_world.as_ref().unwrap();assert_eq!((s.effect_origin,s.effect_flags,s.effect_fade,s.effect_tint,s.effect_owner,s.effect_sprite,s.effect_suppression),([348,532],2,128,seasonal::tint(owner),0,0,0));assert_eq!(g.original_rng.words,rng.words);for slot in 0..cap.min(8){assert_eq!(s.effect_cp_tints[slot],Some(owner));let p=s.effects[slot].as_ref().unwrap();assert_eq!((p.flags,p.tint,p.fade_left,p.fade_interval),(2,seasonal::tint(owner),-128,-128));}}}}}
 #[test]fn destruction_emits_falling_before_eight_points_and_retires_only_after_the_cp_lookup(){for cap in[32,33,40,41]{let mut g=game(0);let mut o=g.make_object(1,[500,600],1).unwrap();o.sprite=5960;o.record.metadata_flags18=14;g.native_world.as_mut().unwrap().objects[0]=Some(o);g.native_world.as_mut().unwrap().effects=vec![None;cap];let mut rng=g.original_rng.clone();for _ in 0..16*6+16*3+usize::from(cap>32)*4+cap.saturating_sub(33).min(8)*5{rng.next_u32();}g.damage_native_world_object(0,2,[500,600]);let s=g.native_world.as_ref().unwrap();assert_eq!(g.original_rng.words,rng.words,"capacity{cap}");assert!(!s.objects[0].as_ref().unwrap().active);assert_eq!(s.objects[0].as_ref().unwrap().record.position[0],-1);if cap>32{let p=s.effects[32].as_ref().unwrap();assert_eq!((p.sprite,p.origin,p.flags),(5960,[340,508],12));assert_eq!(s.effect_cp_tints[32],None);}for slot in 33..cap{let p=s.effects[slot].as_ref().unwrap();assert_eq!((p.origin,p.flags),([348,532],2));assert_eq!(s.effect_cp_tints[slot],Some(0));}assert!(g.native_route_boundary.is_none());}}
 #[test]fn same_callback_draws_keep_their_cp_tag_after_normal_slot_reuse(){let mut g=game(0);g.multiplayer=true;g.native_world.as_mut().unwrap().effects=vec![None];g.emit_native_seasonal_particles([500,608]).unwrap();g.update_native_world_effects();let rows=g.native_world_effects();assert_eq!(rows.len(),1);assert_eq!((rows[0]["colorIndex"].as_u64(),rows[0]["nativeTintOwner"].as_u64()),(Some(24),Some(0)));let s=g.native_world.as_mut().unwrap();s.put_effect(0,effects::initialize(effects::Kind::Hit,[100,100],9,||0));assert_eq!(s.effect_cp_tints[0],None);assert_eq!(g.native_world_effects(),rows,"a later constructor cannot recolor a retained submission");}
 #[test]fn sixteen_clock_comes_from_actual_main_callbacks_and_mission_reset(){let mut g=game(0);g.ai_teams.clear();for team in 0..2{g.spawn("grunt",team,200.+team as f64*1200.,200.,team as usize+1,None);}g.maintain_native_group_rosters();for m in g.native_group_rosters.members.iter_mut().flatten(){m.flags69|=64;}for n in 1..=34{g.step(0.059);assert_eq!(g.native_frame16,n&15);}g.apply_original(&json!({"map":g.map,"sectors":[],"buildings":[],"crates":[],"spawns":[]})).unwrap();assert_eq!(g.native_frame16,0);}
 #[test]fn optional_170_actual_original_callers_match_every_particle_and_rng_word(){let root=std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../../work/parity-audit");let(Ok(text),Ok(cp))=(std::fs::read_to_string(root.join("ROUND39-xmas-particle-callers.jsonl")),std::fs::read("C:/GOG Games/Z/CPUPLR01.DAT"))else{return;};let mut g=game(0);let mut count=0;for line in text.lines(){let r:Value=serde_json::from_str(line).unwrap();let n=|k:&str|r[k].as_i64().unwrap();let scenario=n("scenario")as usize;let cap=n("capacity")as usize;let mut c=pool(0);for slot in 0..64{c.records[slot]=Cp{rect:std::array::from_fn(|i|i16::from_le_bytes(cp[slot*30+i*2..slot*30+i*2+2].try_into().unwrap())),owner:cp[slot*30+8]};}c.records[n("sector")as usize].owner=n("owner")as u8;let state=g.native_world.as_mut().unwrap();state.seasonal_cps=Some(c);state.effects=(0..500).map(|slot|{let mut b=std::array::from_fn(|i|(scenario*17+slot*13+i*19)as u8);b[..2].copy_from_slice(&(if slot<cap{-1000i16}else{0}).to_le_bytes());Some(effects::Particle::from_bytes(b))}).collect();state.effect_cp_tints.fill(None);g.multiplayer=n("mp")!=0;g.original_rng=OriginalRng{words:std::array::from_fn(|i|0x173510a7u32.wrapping_add(scenario as u32*7919).wrapping_add((i as u32).wrapping_mul(0x9e3779b9))),multiplayer:g.multiplayer};assert_eq!(g.emit_native_seasonal_particles([r["point"][0].as_i64().unwrap()as i16,r["point"][1].as_i64().unwrap()as i16]),Ok(n("allocations")as usize));let s=g.native_world.as_ref().unwrap();let hash=s.effects.iter().flatten().flat_map(effects::Particle::bytes).fold(2166136261u32,|h,b|(h^u32::from(b)).wrapping_mul(16777619));assert_eq!(hash,n("poolHash")as u32,"caller{scenario}");assert_eq!(g.original_rng.words,std::array::from_fn(|i|n(&format!("r{i}"))as u32));count+=1;}assert_eq!(count,170);}
 #[test]fn optional_40_original_destruction_prefixes_preserve_warm_records_and_all_rng_words(){let root=std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../../work/parity-audit");let(Ok(text),Ok(cp))=(std::fs::read_to_string(root.join("ROUND39-xmas-destruction-prefix.jsonl")),std::fs::read("C:/GOG Games/Z/CPUPLR01.DAT"))else{return;};let mut count=0;for line in text.lines(){let r:Value=serde_json::from_str(line).unwrap();let n=|k:&str|r[k].as_i64().unwrap();let scenario=n("scenario")as usize;let cap=n("capacity")as usize;let mut g=game(0);let mut c=pool(0);for slot in 0..64{c.records[slot]=Cp{rect:std::array::from_fn(|i|i16::from_le_bytes(cp[slot*30+i*2..slot*30+i*2+2].try_into().unwrap())),owner:cp[slot*30+8]};}let state=g.native_world.as_mut().unwrap();state.seasonal_cps=Some(c);state.effects=(0..500).map(|slot|{let mut b=std::array::from_fn(|i|(scenario*17+slot*13+i*19)as u8);b[..2].copy_from_slice(&(if slot<cap{-1000i16}else{0}).to_le_bytes());Some(effects::Particle::from_bytes(b))}).collect();g.multiplayer=n("mp")!=0;g.native_seasonal_mode=n("mode")as u8;g.original_rng=OriginalRng{words:std::array::from_fn(|i|0x173510a7u32.wrapping_add(scenario as u32*7919).wrapping_add((i as u32).wrapping_mul(0x9e3779b9))),multiplayer:g.multiplayer};g.emit_native_object_falling([232,288],n("base")as i16);if n("mode")==1&&n("base")==5960{g.emit_native_seasonal_particles(seasonal::destruction_point([232,288],n("metadataFlags")as u8)).unwrap();}let s=g.native_world.as_ref().unwrap();let hash=s.effects.iter().flatten().flat_map(effects::Particle::bytes).fold(2166136261u32,|h,b|(h^u32::from(b)).wrapping_mul(16777619));assert_eq!(hash,n("poolHash")as u32,"prefix{scenario}");assert_eq!(g.original_rng.words,std::array::from_fn(|i|n(&format!("r{i}"))as u32));assert_eq!(s.effect_origin,[r["origin"][0].as_i64().unwrap()as i16,r["origin"][1].as_i64().unwrap()as i16]);assert_eq!(s.effect_tint,n("tint")as u8);count+=1;}assert_eq!(count,40);}
}
impl Game{
 ///The actual41eb90 branch's402160→403090 invocation. This uses the same
 ///first-free pool and common raw fields as bridge FX, before402c80.
 pub(super) fn emit_native_object_falling(&mut self,position:[i16;2],sprite:i16){use super::effects::{Particle,bridge::{self,Globals},spray::Context};let Some(s)=&mut self.native_world else{return;};s.effect_origin=[position[0].wrapping_sub(160),position[1].wrapping_sub(92)];s.effect_fade=0;s.effect_flags=12;s.effect_owner=0;s.effect_maximum=0;s.effect_sprite=sprite;s.bridge_fx.constructor=Some(0x403090);if s.effect_suppression!=0{return;}let Some(slot)=s.effects.iter().position(|p|p.as_ref().is_none_or(|p|p.position[0]==-1000))else{return;};let mut bytes=s.effects[slot].as_ref().map_or([0;44],Particle::bytes);let g=Globals{context:Context{origin:s.effect_origin,tint:s.effect_tint,flags:s.effect_flags,fade:s.effect_fade,owner:s.effect_owner,sprite:s.effect_sprite},maximum:s.effect_maximum as u8,suppression:s.effect_suppression,raw:s.bridge_fx};bridge::common(&mut bytes,&g);s.bridge_fx.last_record=Some(bridge::NATIVE_POOL.wrapping_add((slot as u32).wrapping_mul(44)));self.original_rng.multiplayer=self.multiplayer;seasonal::falling(&mut bytes,||self.original_rng.next_u32());s.put_effect(slot,Particle::from_bytes(bytes));}
 fn native_seasonal_owner(&self,point:[i16;2])->Result<u8,Boundary>{let pool=self.native_world.as_ref().and_then(|s|s.seasonal_cps.as_ref()).ok_or(Boundary::SeasonalCpPool)?;let mut records=pool.records;for(slot,binding)in pool.bindings.iter().enumerate(){let Some(live)=binding.and_then(|id|self.sectors.iter().find(|s|s.id==id))else{continue;};let initial=if records[slot].owner<4{i32::from(records[slot].owner)}else{-1};if live.owner!=initial{records[slot].owner=if(0..4).contains(&live.owner){live.owner as u8}else{4};}}
  let hit=seasonal::cp_at(&records,point).ok_or(Boundary::SeasonalCpLookup(point))?;if hit.outside_mode{return Err(Boundary::SeasonalCpOutsideMode);}Ok(records[hit.slot].owner)
 }
 ///True means this is the separate5960 branch, including its visibility
 ///and explicit missing-CP boundaries. It must not fall through to wrecks.
 pub(super) fn capture_native_seasonal_object(&mut self,slot:usize,input:display::ObjectInput,camera:[i16;2],size:[i16;2])->bool{
  if !seasonal::tree(input,self.native_seasonal_mode){return false;}if !display::objects::visible(input.position,camera,size){return true;}
  let rows=(||{let owner=self.native_seasonal_owner(seasonal::cp_point(input))?;seasonal::rows(input,self.native_frame16,owner).map_err(Boundary::SeasonalClock16)})();match rows{Ok(rows)=>for(part,r)in rows.into_iter().enumerate(){self.store_native_object_picture(slot,r,["object","seasonalFlag","seasonalOverlay"][part],part==2);},Err(e)=>self.native_route_boundary=Some(e)}true
 }
 ///402c80 receives the41eb90 argument(x,y+8), after FallingObject and
 ///before the doomed OBJECT's X sentinel. Its count is always eight.
 pub(super) fn emit_native_seasonal_particles(&mut self,point:[i16;2])->Result<usize,Boundary>{
  let state=self.native_world.as_mut().ok_or(Boundary::SeasonalCpPool)?;state.effect_origin=[point[0].wrapping_sub(152),point[1].wrapping_sub(76)];state.effect_flags=2;state.effect_fade=128;state.effect_owner=0;state.effect_sprite=0;
  let owner=self.native_seasonal_owner(point)?;let state=self.native_world.as_mut().unwrap();state.effect_tint=seasonal::tint(owner);state.effect_suppression=0;Ok(self.emit_native_spray_with_cp(8,Some(owner)))
 }
}
